import{_ as s,o as t,c as a,a2 as e}from"./chunks/framework.Lq8Lraw_.js";const k=JSON.parse('{"title":"01 版本控制与 Git 的定位","description":"","frontmatter":{},"headers":[],"relativePath":"guide/basics/01-version-control.md","filePath":"guide/basics/01-version-control.md","lastUpdated":1792671989000}'),n={name:"guide/basics/01-version-control.md"};function l(d,i,o,p,h,c){return t(),a("div",null,[...i[0]||(i[0]=[e(`<h1 id="_01-版本控制与-git-的定位" tabindex="-1">01 版本控制与 Git 的定位 <a class="header-anchor" href="#_01-版本控制与-git-的定位" aria-label="Permalink to &quot;01 版本控制与 Git 的定位&quot;">​</a></h1><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>能说明版本控制在「可追溯、可回滚、可协作」三个维度上解决的问题。</li><li>能对比集中式（Centralized VCS）与分布式（Distributed VCS）在存储与离线能力上的差异。</li><li>能用自己的话解释 Git 的「快照（snapshot）而非差异（diff）」模型。</li><li>能识别工作目录与 <code>.git</code> 目录的职责边界，并用 <code>git init</code>、<code>git clone</code> 创建仓库。</li><li>能判断 Git 在需求、开发、测试、发布链路中的位置。</li></ul><h2 id="为什么需要版本控制" tabindex="-1">为什么需要版本控制 <a class="header-anchor" href="#为什么需要版本控制" aria-label="Permalink to &quot;为什么需要版本控制&quot;">​</a></h2><p>没有版本控制时，团队通常靠文件名区分版本：<code>需求_v1.docx</code>、<code>需求_v2_最终版.docx</code>、<code>需求_v2_最终版_改.docx</code>。这套做法的问题不是「乱」，而是无法回答几个关键问题：</p><ul><li>某一行代码是谁、在什么时候、为什么改的？</li><li>上周五还能跑的功能，是哪一个改动弄坏的？</li><li>两个人同时改同一个文件，如何合并而不是互相覆盖？</li><li>线上出故障时，如何精确回到上一个可用版本？</li></ul><p>版本控制系统（Version Control System，VCS）把这些问题收敛为三个能力：</p><table tabindex="0"><thead><tr><th>能力</th><th>具体表现</th></tr></thead><tbody><tr><td>可追溯</td><td>每次变更都有作者、时间、说明和完整内容</td></tr><tr><td>可回滚</td><td>任意历史版本都能检出，且不影响其他版本</td></tr><tr><td>可协作</td><td>多人在各自副本上开发，再通过明确机制合并</td></tr></tbody></table><p>对开发者而言，Git 不只是「备份工具」，它是代码变更的事实来源（source of truth）。代码评审、持续集成（CI）、发布、故障定位都建立在提交历史之上。</p><h2 id="集中式与分布式" tabindex="-1">集中式与分布式 <a class="header-anchor" href="#集中式与分布式" aria-label="Permalink to &quot;集中式与分布式&quot;">​</a></h2><p>集中式版本控制的代表是 SVN。仓库只有一份，放在中央服务器；开发者检出（checkout）工作副本，提交时直接写服务器，因此提交必须联网。分支通常通过目录拷贝实现，成本高，团队往往不敢频繁开分支。</p><p>分布式版本控制的代表是 Git。每次 <code>git clone</code> 得到的不只是最新文件，而是包含全部历史的完整仓库。提交先写本地数据库，只有 <code>git push</code> 才需要网络。分支只是一个指针，创建和切换几乎零成本。</p><table tabindex="0"><thead><tr><th>维度</th><th>集中式（SVN）</th><th>分布式（Git）</th></tr></thead><tbody><tr><td>仓库位置</td><td>仅中央服务器</td><td>每个克隆都是完整仓库</td></tr><tr><td>提交</td><td>直接写服务器，需联网</td><td>先本地提交，推送时才联网</td></tr><tr><td>历史</td><td>依赖服务器</td><td>本地拥有完整历史</td></tr><tr><td>分支</td><td>目录拷贝，成本高</td><td>指针移动，成本极低</td></tr><tr><td>离线工作</td><td>基本不可用</td><td>可提交、查历史、切分支</td></tr><tr><td>版本标识</td><td>全局递增版本号</td><td>内容哈希（commit SHA）</td></tr></tbody></table><p>需要强调：分布式不等于不需要远程仓库。团队仍然会用 GitHub、GitLab 作为共享中心，但它只是「多个完整仓库中的一个」，而不是唯一数据源。</p><h2 id="快照而非差异" tabindex="-1">快照而非差异 <a class="header-anchor" href="#快照而非差异" aria-label="Permalink to &quot;快照而非差异&quot;">​</a></h2><p>传统版本控制倾向于保存「文件相对上一版的差异」，读取某个版本时需要从头叠加补丁。Git 的做法不同：每次提交（commit）保存的是当时整个项目的一份快照（snapshot）。</p><p>为了不把未修改的文件重复存一遍，Git 用内容寻址（content-addressed）的方式存储对象：文件内容计算出哈希值作为对象 ID，内容相同的文件只存一份。快照中的目录树（tree）引用这些对象，提交对象（commit）再引用目录树和父提交。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>commit 3f2a1c9</span></span>
<span class="line"><span>  └── tree（项目根目录快照）</span></span>
<span class="line"><span>        ├── blob a1b2c3  README.md</span></span>
<span class="line"><span>        └── tree 4d5e6f  src/</span></span>
<span class="line"><span>              └── blob 7a8b9c  main.ts   ← 与上一提交内容相同，复用同一对象</span></span>
<span class="line"><span></span></span>
<span class="line"><span>commit 8b1e0d4  ← 父提交，同样指向一棵 tree</span></span></code></pre></div><p>因此：</p><ul><li>查看历史版本是「取出某棵 tree」，不需要重放补丁。</li><li>比较两个版本时才临时计算差异，<code>git diff</code> 是结果而非存储形式。</li><li>任何内容一旦写入对象库就不可变，修改文件只会产生新对象。</li></ul><p>这也解释了为什么提交哈希能作为版本唯一标识：它由内容、父提交、作者和时间共同决定，篡改历史必然改变哈希。</p><h2 id="工作目录与-git-目录" tabindex="-1">工作目录与 .git 目录 <a class="header-anchor" href="#工作目录与-git-目录" aria-label="Permalink to &quot;工作目录与 .git 目录&quot;">​</a></h2><p>一个 Git 仓库由两部分组成：</p><ul><li>工作目录（working tree）：你实际编辑的文件，普通目录结构。</li><li><code>.git</code> 目录：仓库数据库与配置，包含对象、引用、索引、钩子等。</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .  ..  .git  README.md  src</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .git</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># HEAD  config  description  hooks  index  info  logs  objects  refs</span></span></code></pre></div><p>几个关键条目：</p><table tabindex="0"><thead><tr><th>路径</th><th>作用</th></tr></thead><tbody><tr><td><code>.git/objects</code></td><td>所有文件内容、目录树、提交对象</td></tr><tr><td><code>.git/refs/heads</code></td><td>本地分支指针，每个文件内容是一个提交哈希</td></tr><tr><td><code>.git/HEAD</code></td><td>当前所在分支的引用</td></tr><tr><td><code>.git/index</code></td><td>暂存区（staging area）的二进制记录</td></tr><tr><td><code>.git/config</code></td><td>当前仓库的本地配置</td></tr><tr><td><code>.git/logs</code></td><td>reflog，记录 HEAD 与分支的移动历史</td></tr></tbody></table><p>删除 <code>.git</code> 等于删除全部历史，工作目录会退化成一个普通文件夹。反过来，拷贝项目时带上 <code>.git</code>，就把完整历史一起带走了。</p><div class="tip custom-block"><p class="custom-block-title">快速判断当前目录是否在仓库内</p><p><code>git rev-parse --is-inside-work-tree</code> 输出 <code>true</code> 表示在工作目录内；输出 <code>fatal: not a git repository</code> 表示不在任何仓库中。</p></div><h2 id="最小演示-init-与-clone" tabindex="-1">最小演示：init 与 clone <a class="header-anchor" href="#最小演示-init-与-clone" aria-label="Permalink to &quot;最小演示：init 与 clone&quot;">​</a></h2><p>从零创建一个仓库：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git-demo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git-demo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Initialized empty Git repository in /Users/you/git-demo/.git/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On branch main</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># No commits yet</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># nothing to commit (create/copy files and use &quot;git add&quot; to track)</span></span></code></pre></div><p>如果初始化提示 <code>On branch master</code>，说明 <code>init.defaultBranch</code> 仍是旧默认值，可在下一篇配置为 <code>main</code>。</p><p>创建第一个提交：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;# Git Demo&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> README.md</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> README.md</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;chore: 初始化仓库&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [main (root-commit) 3f2a1c9] chore: 初始化仓库</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  1 file changed, 1 insertion(+)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3f2a1c9 chore: 初始化仓库</span></span></code></pre></div><p>从远程获取一个已有仓库：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/octocat/Hello-World.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Hello-World</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -3</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 7fd1a60 Merge pull request #6 from ...</span></span></code></pre></div><p><code>git clone</code> 等价于：初始化本地仓库、登记远程地址（<code>origin</code>）、拉取全部对象、创建工作分支并检出。默认会取完整历史；<code>--depth 1</code> 可做浅克隆，只取最近一次提交，适合 CI，但不适合需要查历史或做合并的场景。</p><h2 id="git-在研发链路中的位置" tabindex="-1">Git 在研发链路中的位置 <a class="header-anchor" href="#git-在研发链路中的位置" aria-label="Permalink to &quot;Git 在研发链路中的位置&quot;">​</a></h2><p>一个典型的企业研发链路中，Git 承担「代码变更的记录与流转」：</p><ol><li>需求拆分为任务，从主干拉出功能分支。</li><li>开发者在本地以小提交推进，每个提交可独立解释。</li><li>推送分支，发起合并请求（Pull Request / Merge Request）。</li><li>CI 在提交上运行测试与静态检查，评审在差异上进行。</li><li>合并回主干，按发布节奏打标签（tag）。</li><li>线上问题通过回滚提交或热修复分支处理。</li></ol><p>Git 不负责需求管理、构建产物和部署状态，但它为这些系统提供稳定的版本坐标：CI 跑在哪个提交、镜像由哪个提交构建、线上运行的是哪个 tag，都应能追溯到唯一的 commit 哈希。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">不要把 <code>.git</code> 当普通目录操作</p><p>手动删除 <code>.git/refs</code>、编辑 <code>.git/HEAD</code>、用文件管理器覆盖 <code>.git</code>，都可能让仓库无法识别。需要修改引用时使用 <code>git branch</code>、<code>git switch</code>、<code>git update-ref</code> 等命令，让 Git 自己维护一致性。</p></div><div class="warning custom-block"><p class="custom-block-title">克隆下来的仓库不是「只读副本」</p><p>本地克隆拥有完整历史，可以随意提交、重置、变基。这些操作在推送前只影响本地；一旦推送，就会影响所有协作者。权限控制应放在远程仓库，而不是指望本地副本「不会改」。</p></div><div class="warning custom-block"><p class="custom-block-title">用网盘同步工作目录会损坏仓库</p><p>把包含 <code>.git</code> 的目录放进 iCloud、OneDrive、Dropbox 实时同步，可能在写入对象时产生冲突文件，导致索引或对象损坏。需要备份时使用 <code>git push</code> 或 <code>git bundle</code>。</p></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>版本控制解决的是可追溯、可回滚、可协作，Git 是代码变更的事实来源。</li><li>分布式意味着每个克隆都有完整历史，提交在本地完成，推送才需要网络。</li><li>Git 保存提交时刻的完整快照，通过内容哈希去重复用对象，差异是临时计算出来的。</li><li>工作目录是可见文件，<code>.git</code> 是仓库数据库；删除 <code>.git</code> 就删除了历史。</li><li><code>git init</code> 从零建库，<code>git clone</code> 复制完整仓库并建立远程关联。</li></ul><p>下一步：<a href="/git-tutorial-site/guide/basics/02-install-config">02 安装与第一次配置</a>，先把环境和身份配置正确，再开始日常提交。</p>`,49)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
